+use crate::api::client::ApiClient;
+use crate::models::{ResultWithDefaultError, TimeEntry};
+use crate::utilities;
+use std::collections::BTreeMap;
+
+/// Return the duration used by invoices. Running entries have no invoiceable
+/// duration; stopped entries use their recorded duration, never a negative
+/// API sentinel.
+fn invoice_seconds(entry: &TimeEntry) -> Option<i64> {
+    if !entry.billable || entry.is_running() || entry.stop.is_none() {
+        return None;
+    }
+    Some(entry.duration.max(0))
+}
+
+pub struct InvoiceMonthlyCommand;
+
+impl InvoiceMonthlyCommand {
+    pub async fn execute(
+        api_client: impl ApiClient,
+        since: Option<String>,
+        until: Option<String>,
+    ) -> ResultWithDefaultError<()> {
+        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
+        let entries = api_client
+            .get_time_entries_filtered_minimal(since, until)
+            .await?;
+
+        let mut months = BTreeMap::<String, i64>::new();
+        for entry in &entries {
+            if let Some(seconds) = invoice_seconds(entry) {
+                let month = entry.start.format("%Y-%m").to_string();
+                *months.entry(month).or_default() += seconds;
+            }
+        }
+
+        if months.is_empty() {
+            println!("(no data)");
+            return Ok(());
+        }
+
+        for (month, seconds) in &months {
+            println!("{month}  {seconds}s");
+        }
+        let total: i64 = months.values().sum();
+        println!("Total  {total}s");
+        Ok(())
+    }
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    use crate::api::client::MockApiClient;
+    use chrono::{TimeZone, Utc};
+
+    fn entry(start: &str, duration: i64, billable: bool, stopped: bool) -> TimeEntry {
+        let start = Utc.datetime_from_str(start, "%Y-%m-%dT%H:%M:%SZ").unwrap();
+        TimeEntry {
+            id: 1,
+            description: String::new(),
+            start,
+            stop: stopped.then_some(start),
+            duration,
+            billable,
+            workspace_id: 1,
+            tags: vec![],
+            project: None,
+            task: None,
+            created_with: None,
+        }
+    }
+
+    #[test]
+    fn invoice_rule_excludes_non_billable_and_running_entries() {
+        assert_eq!(invoice_seconds(&entry("2026-01-01T00:00:00Z", 10, false, true)), None);
+        assert_eq!(invoice_seconds(&entry("2026-01-01T00:00:00Z", -10, true, false)), None);
+        assert_eq!(invoice_seconds(&entry("2026-01-01T00:00:00Z", 10, true, true)), Some(10));
+    }
+
+    #[tokio::test]
+    async fn monthly_invoice_uses_utc_month_and_chronological_order() {
+        let mut api = MockApiClient::new();
+        api.expect_get_time_entries_filtered_minimal()
+            .returning(|_, _| {
+                Ok(vec![
+                    entry("2026-02-01T00:00:00Z", 20, true, true),
+                    entry("2026-01-31T23:30:00Z", 10, true, true),
+                ])
+            });
+        InvoiceMonthlyCommand::execute(api, None, None).await.unwrap();
+    }
+}
